/* ── design tokens ────────────────────────────────────────────── */
:root {
  --jh-green:      #1a6e57;
  --jh-green-d:    #134f3e;
  --jh-green-l:    #e8f5f0;
  --jh-green-m:    #d0ece4;
  --jh-gold:       #c9960c;
  --jh-gold-l:     #f6c90e;
  --jh-gold-bg:    #fffbea;
  --jh-gold-brd:   #e8b80d;
  --jh-dark:       #0f2e25;
  --jh-text:       #1d2228;
  --jh-muted:      #5a6672;
  --jh-border:     #d6e6df;
  --jh-radius:     14px;
  --jh-radius-sm:  8px;
  --jh-shadow:     0 6px 32px rgba(26,110,87,.13);
  --jh-shadow-sm:  0 2px 12px rgba(26,110,87,.09);
  --jh-tr:         .2s ease;
}

/* ── page shell ───────────────────────────────────────────────── */
#jh {
  font-family: "Segoe UI", system-ui, sans-serif;
  color: var(--jh-text);
  font-size: 15px;
  max-width: 1060px;
  margin: 0 auto;
  padding: 0 1.1rem 4rem;
}

/* ── hero ─────────────────────────────────────────────────────── */
.jh-hero {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
  flex-wrap: wrap;
  padding: 3.2rem 3rem;
  margin-bottom: 2.5rem;
  background: linear-gradient(135deg, #134f3e 0%, #1a6e57 55%, #22896b 100%);
  border-radius: 14px;
  box-shadow: 0 6px 32px rgba(26,110,87,.13);
  position: relative;
  overflow: hidden;
}
.jh-hero::before,
.jh-hero::after {
  content: "";
  position: absolute;
  border-radius: 50%;
  border: 2px solid rgba(201,150,12,.18);
  pointer-events: none;
}
.jh-hero::before { width: 320px; height: 320px; top: -80px; right: -60px; }
.jh-hero::after  { width: 200px; height: 200px; bottom: -70px; right: 60px; }

.jh-hero-left { flex: 1 1 340px; z-index: 1; }

.jh-hero h1 {
  font-size: 2rem;
  font-weight: 800;
  color: #fff;
  margin: 0 0 .45rem;
  line-height: 1.2;
  letter-spacing: -.01em;
}
.jh-hero h1 span { color: #f6c90e; }

.jh-tagline {
  color: rgba(255,255,255,.82);
  font-size: .98rem;
  margin: 0 0 1.6rem;
  max-width: 400px;
  line-height: 1.6;
}

/* ── hero buttons ────────────────────────────────────────────── */
.jh-hero-btns { display: flex; gap: .75rem; flex-wrap: wrap; }

.jh-btn {
  display: inline-flex;
  align-items: center;
  gap: .4rem;
  padding: .65rem 1.45rem;
  border-radius: 8px;
  font-size: .95rem;
  font-weight: 700;
  text-decoration: none;
  transition: background .2s ease, box-shadow .2s ease, transform .2s ease;
  cursor: pointer;
  border: none;
}
.jh-btn:hover { transform: translateY(-1px); }

.jh-btn-gold {
  background: linear-gradient(135deg, #f6c90e, #c9960c);
  color: #2a1800;
  box-shadow: 0 3px 14px rgba(201,150,12,.45);
}
.jh-btn-gold:hover {
  box-shadow: 0 5px 20px rgba(201,150,12,.6);
  color: #1a1000;
  text-decoration: none;
}
.jh-btn-ghost {
  background: rgba(255,255,255,.12);
  color: #fff;
  border: 1.5px solid rgba(255,255,255,.35);
}
.jh-btn-ghost:hover {
  background: rgba(255,255,255,.22);
  color: #fff;
  text-decoration: none;
}

/* ── timing card ─────────────────────────────────────────────── */
.jh-hero-right { z-index: 1; flex-shrink: 0; }

.jh-timing {
  background: rgba(255,255,255,.10);
  border: 1.5px solid rgba(201,150,12,.35);
  border-radius: 14px;
  padding: 1.5rem 1.8rem;
  text-align: center;
  min-width: 220px;
  box-shadow: 0 4px 20px rgba(0,0,0,.18);
}
.jh-timing-badge {
  display: inline-block;
  background: linear-gradient(135deg, #f6c90e, #c9960c);
  color: #2a1800;
  font-size: .72rem;
  font-weight: 800;
  letter-spacing: .08em;
  text-transform: uppercase;
  border-radius: 20px;
  padding: .22rem .8rem;
  margin-bottom: .9rem;
}
.jh-timing h4 {
  color: #fff;
  font-size: .85rem;
  font-weight: 600;
  letter-spacing: .04em;
  text-transform: uppercase;
  margin: 0 0 .5rem;
  opacity: .75;
}
.jh-time-val {
  color: #fff;
  font-size: 1.35rem;
  font-weight: 800;
  margin: 0 0 .15rem;
}
.jh-time-days {
  color: #f6c90e;
  font-size: .82rem;
  font-weight: 600;
  margin: 0 0 1rem;
}
.jh-timing-divider {
  border: none;
  border-top: 1px solid rgba(255,255,255,.15);
  margin: .9rem 0;
}
.jh-timing-phone { color: rgba(255,255,255,.7); font-size: .78rem; }
.jh-timing-phone a { color: #f6c90e; font-weight: 700; text-decoration: none; font-size: .84rem; }
.jh-timing-phone a:hover { text-decoration: underline; }

/* ── section header ──────────────────────────────────────────── */
.jh-section-hd { text-align: center; margin-bottom: 1.6rem; }
.jh-section-hd h2 {
  font-size: 1.45rem;
  font-weight: 800;
  color: #1a6e57;
  margin: 0 0 .35rem;
}
.jh-section-hd p { color: #5a6672; font-size: .93rem; margin: 0; }
.jh-section-hd h2::after {
  content: "";
  display: block;
  width: 48px;
  height: 3px;
  border-radius: 2px;
  background: linear-gradient(90deg, #f6c90e, #c9960c);
  margin: .45rem auto 0;
}

/* ── service cards ───────────────────────────────────────────── */
.jh-services {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.1rem;
  margin-bottom: 2.5rem;
}
@media (max-width: 680px) {
  .jh-services { grid-template-columns: 1fr; }
  .jh-hero { padding: 2rem 1.4rem; }
  .jh-hero h1 { font-size: 1.55rem; }
}
@media (min-width: 481px) and (max-width: 680px) {
  .jh-services { grid-template-columns: 1fr 1fr; }
}

.jh-svc {
  background: #fff;
  border: 1.5px solid #d6e6df;
  border-radius: 14px;
  padding: 1.6rem 1.4rem 1.5rem;
  box-shadow: 0 2px 12px rgba(26,110,87,.09);
  transition: box-shadow .2s ease, border-color .2s ease, transform .2s ease;
  position: relative;
  overflow: hidden;
}
.jh-svc:hover {
  box-shadow: 0 6px 32px rgba(26,110,87,.13);
  border-color: #1a6e57;
  transform: translateY(-2px);
}
.jh-svc::before {
  content: "";
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 3px;
  background: linear-gradient(90deg, #f6c90e, #c9960c);
  border-radius: 14px 14px 0 0;
}
.jh-svc-icon {
  width: 48px; height: 48px;
  border-radius: 12px;
  background: #e8f5f0;
  display: flex; align-items: center; justify-content: center;
  font-size: 1.5rem;
  margin-bottom: 1rem;
  border: 1.5px solid #d0ece4;
}
.jh-svc h3 { font-size: 1rem; font-weight: 700; color: #134f3e; margin: 0 0 .5rem; }
.jh-svc p  { font-size: .86rem; color: #5a6672; margin: 0; line-height: 1.6; }

/* ── info strip ──────────────────────────────────────────────── */
.jh-strip {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
  background: linear-gradient(135deg, #fffbea, #fff8d6);
  border: 1.5px solid #e8b80d;
  border-radius: 14px;
  padding: 1.3rem 1.6rem;
  margin-bottom: 2.5rem;
  align-items: center;
}
.jh-strip-icon { font-size: 1.8rem; flex-shrink: 0; }
.jh-strip-text { flex: 1 1 200px; }
.jh-strip-text strong {
  display: block;
  color: #c9960c;
  font-size: .78rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: .06em;
  margin-bottom: .2rem;
}
.jh-strip-text p { color: #1d2228; font-size: .9rem; margin: 0; line-height: 1.5; }

/* ── why-us grid ─────────────────────────────────────────────── */
.jh-why {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1rem;
  margin-bottom: 2.5rem;
}
@media (max-width: 480px) { .jh-why { grid-template-columns: 1fr; } }

.jh-why-item {
  display: flex;
  gap: .85rem;
  align-items: flex-start;
  background: #fff;
  border: 1.5px solid #d6e6df;
  border-radius: 8px;
  padding: 1.1rem 1.2rem;
  box-shadow: 0 2px 12px rgba(26,110,87,.09);
}
.jh-why-dot {
  width: 36px; height: 36px;
  border-radius: 50%;
  background: #e8f5f0;
  border: 2px solid #d0ece4;
  display: flex; align-items: center; justify-content: center;
  font-size: 1rem;
  flex-shrink: 0;
}
.jh-why-item h4 { font-size: .92rem; font-weight: 700; color: #134f3e; margin: 0 0 .25rem; }
.jh-why-item p  { font-size: .82rem; color: #5a6672; margin: 0; line-height: 1.55; }

/* ── CTA banner ──────────────────────────────────────────────── */
.jh-cta {
  background: linear-gradient(135deg, #0f2e25 0%, #134f3e 100%);
  border-radius: 14px;
  padding: 2.2rem 2.4rem;
  text-align: center;
  box-shadow: 0 6px 32px rgba(26,110,87,.13);
  position: relative;
  overflow: hidden;
}
.jh-cta::before {
  content: "";
  position: absolute;
  width: 260px; height: 260px;
  border-radius: 50%;
  background: rgba(201,150,12,.08);
  top: -100px; left: -60px;
  pointer-events: none;
}
.jh-cta h2 { color: #fff; font-size: 1.35rem; font-weight: 800; margin: 0 0 .5rem; }
.jh-cta p  { color: rgba(255,255,255,.72); font-size: .93rem; margin: 0 0 1.4rem; }
.jh-cta-btns {
  display: flex; gap: .75rem;
  justify-content: center; flex-wrap: wrap;
}

#as *{box-sizing:border-box;margin:0;padding:0}
  #as{font:15px/1.5 system-ui,sans-serif;color:#1c1b1f;max-width:680px;margin:0 auto;padding:14px 10px 80px}
  #as .top{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;gap:10px}
  #as h1{font-size:1.4rem;font-weight:700}
  #as h2{font-size:1.05rem;font-weight:700;margin-bottom:10px}
  #as .card{background:#fff;border:1px solid #e0e0e0;border-radius:12px;padding:14px;margin-bottom:12px}
  #as label{display:block;font-size:.82rem;font-weight:600;color:#555;margin-top:10px;margin-bottom:3px}
  #as label:first-child{margin-top:0}
  #as input,#as select{width:100%;border:1px solid #c4c7c5;border-radius:8px;padding:9px 11px;font:15px system-ui;background:#fff;color:#1c1b1f}
  #as input:focus,#as select:focus{outline:2px solid #1a73e8;border-color:transparent}
  #as .btn{background:#1a73e8;color:#fff;border:none;border-radius:8px;padding:10px 18px;font:600 15px system-ui;cursor:pointer;white-space:nowrap;text-decoration:none;display:inline-block;text-align:center}
  #as .btn:disabled{opacity:.5;cursor:default}
  #as .btn.go{background:#188038}
  #as .link{background:none;border:none;color:#1a73e8;font:15px system-ui;cursor:pointer;padding:0;text-decoration:underline}
  #as .back-link{color:#1a73e8;font-size:.9rem;text-decoration:none;font-weight:600;display:inline-flex;align-items:center;gap:4px;margin-bottom:10px}
  #as .split{display:flex;justify-content:space-between;align-items:flex-start;gap:8px}
  #as .hint{font-size:.82rem;color:#777;margin-top:4px}
  #as .mute{color:#777}
  #as #toast{padding:10px 14px;border-radius:8px;font-size:.9rem;margin:8px 0;background:#e6f4ea;color:#1e8e3e}
  #as #toast.bad{background:#fdf0ef;color:#b3261e}
  #as .g2{display:grid;grid-template-columns:1fr 1fr;gap:10px}
  #as .sum{display:flex;justify-content:space-between;align-items:center;padding:7px 0;border-top:1px solid #eee;font-size:.92rem}
  @media(max-width:520px){
    #as .g2{grid-template-columns:1fr}
  }

html,body{height:auto!important;min-height:100%!important;overflow-y:auto!important}
#en{--ink:#16324a;--mute:#5d7184;--line:#cfdad5;--bg:#f3f8f5;--ok:#1d7a5f;--err:#b3261e;display:flex;flex-direction:column;gap:12px;box-sizing:border-box;min-height:100vh;height:auto!important;max-width:1880px;margin:0 auto;padding:8px 8px 60px;color:var(--ink);font:15px/1.4 system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;overflow:visible!important}
.web-footer,body>footer{display:none!important}
#en *{box-sizing:border-box}
#en a.back{color:#cfeee2;font-weight:600;text-decoration:none;font-size:.9rem;white-space:nowrap}
#en .pt{flex:none;display:flex;gap:14px;align-items:center;padding:8px 14px;border-radius:12px;background:var(--ink);color:#fff}
#en .av{flex:none;width:40px;height:40px;border-radius:50%;background:#8cc9b5;color:var(--ink);display:grid;place-items:center;font-weight:800}
#en h1{font-size:1.25rem;margin:0;line-height:1.2}
#en .pt p{margin:0;font-size:.88rem;opacity:.88}
#en .pt .ap{margin-left:auto;text-align:right;font-size:.85rem}
#en .pt .ap b{display:block;font-size:1rem}
#en h2{font-size:.95rem;margin:0 0 8px}
#en .card{padding:12px 14px;border:1.5px solid var(--line);border-radius:12px;background:#fff}
#en label{display:block;font-size:.76rem;font-weight:600;margin:0 0 2px;color:var(--mute)}
#en input,#en select,#en textarea{width:100%;padding:7px 9px;border:1.5px solid var(--line);border-radius:8px;font:inherit;color:var(--ink);background:#fff}
#en input:focus,#en select:focus,#en textarea:focus,#en button:focus-visible{outline:3px solid #8cc9b5;outline-offset:1px}

#en #form{display:grid;grid-template-columns:1fr 1fr;gap:12px;align-items:start}
#en #sec-hx{grid-column:1/-1;background:#f8faf9}
#en #sec-vitals{grid-column:1/-1}
#en #sec-sym{grid-column:1}
#en #sec-dx{grid-column:2}
#en #sec-meds{grid-column:1/-1}
#en #sec-lab{grid-column:1}
#en #sec-notes{grid-column:2}
#en #acts{grid-column:1/-1}

#en .hx-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:6px}
#en .hx-head h2{margin:0;font-size:.95rem}
#en #hx{display:flex;flex-direction:column;gap:6px;max-height:160px;overflow-y:auto}
#en .hx-row{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:8px;padding:6px 10px;background:#fff;border:1px solid var(--line);border-radius:8px;font-size:.88rem}
#en .hx-info{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
#en a.hx-date{font-weight:700;color:var(--ink);text-decoration:none;border-bottom:1.5px solid #8cc9b5}
#en a.hx-date:hover{color:var(--ok)}
#en .hx-dx{background:var(--bg);color:var(--ok);padding:2px 8px;border-radius:6px;font-weight:600;font-size:.82rem;border:1px solid var(--line)}
#en .hx-note{color:var(--mute);font-size:.84rem}
#en .hx-actions{display:flex;gap:6px;align-items:center;margin-left:auto}
#en .hx-btn{display:inline-flex;align-items:center;padding:3px 8px;border-radius:6px;border:1px solid var(--line);background:#fff;color:var(--ink);font-size:.8rem;font-weight:600;text-decoration:none}
#en .hx-btn:hover{background:var(--bg);border-color:var(--ink)}

#en .vg{display:grid;grid-template-columns:repeat(8,1fr);gap:8px}
#en .tags{flex:1;display:flex;flex-wrap:wrap;align-content:flex-start;gap:5px;padding:5px;min-height:58px;border:1.5px solid var(--line);border-radius:8px}
#en .tags input{flex:1 1 130px;border:0;padding:4px;min-width:0}
#en .tags input:focus{outline:none}
#en .tags:focus-within{outline:3px solid #8cc9b5}
#en .chip{display:inline-flex;gap:4px;align-items:center;padding:2px 3px 2px 9px;border-radius:999px;background:var(--bg);border:1px solid var(--line);font-size:.9rem}
#en .chip.new{border-style:dashed}
#en .chip button{border:0;background:none;color:var(--mute);font-size:1.1rem;line-height:1;cursor:pointer;padding:2px 6px}

#en .meds{display:flex;flex-direction:column;gap:10px}
#en #meds{display:flex;flex-direction:column;gap:8px}
#en .med{background:#fdfefe;border:1.5px solid var(--line);border-radius:10px;padding:10px 12px;display:flex;flex-direction:column;gap:8px}
#en .med-row{display:grid;grid-template-columns:minmax(180px,2.4fr) 115px 115px 115px minmax(140px,1.8fr) auto;gap:8px;align-items:end}
#en .med button.rm{height:38px;padding:0 14px;border:1.5px solid var(--err);background:#fff;color:var(--err);border-radius:8px;font-weight:600;cursor:pointer;white-space:nowrap}
#en .med button.rm:hover{background:var(--err);color:#fff}
#en .nn{padding:8px 0 2px;margin-top:2px;border-top:1px dashed var(--line)}
#en .nn .hint{margin:0 0 6px;font-size:.82rem;color:var(--mute);display:block}
#en .nn-fields{display:grid;grid-template-columns:minmax(180px,1.5fr) 120px 120px;gap:8px;max-width:600px;align-items:end}
#en .mf{display:flex;gap:10px;align-items:center;padding-top:4px}
#en button.sm{padding:7px 14px;border:1.5px solid var(--ink);border-radius:8px;background:#fff;color:var(--ink);font:inherit;font-weight:600;cursor:pointer}
#en .hint{color:var(--mute);font-size:.85rem;margin:0}

#en #notes{min-height:58px;resize:vertical}

#en .acts{display:flex;gap:12px;justify-content:flex-end;align-items:center;flex-wrap:wrap;padding:16px 0 32px;margin-top:4px;border-top:1.5px solid var(--line)}
#en .acts button,#en .acts a.pb{padding:12px 24px;border-radius:10px;font:inherit;font-weight:700;font-size:1rem;cursor:pointer;text-decoration:none;display:inline-flex;align-items:center;justify-content:center}
#en .acts button{border:1.5px solid var(--ink);background:#fff;color:var(--ink)}
#en .acts button.go,#en .acts a.pb{background:var(--ok);border:1.5px solid var(--ok);color:#fff}
#en .acts button.go:hover,#en .acts a.pb:hover{filter:brightness(.92)}
#en .acts button:disabled{opacity:.55;cursor:wait}

#en .note{padding:9px 14px;border-radius:8px;background:var(--bg);border-left:4px solid var(--ok)}
#en .note.bad{border-color:var(--err);background:#fdf0ef}
#en [hidden]{display:none!important}

@media(max-width:960px){
  #en #form{grid-template-columns:1fr}
  #en #sec-sym,#en #sec-dx,#en #sec-lab,#en #sec-notes{grid-column:1}
  #en .vg{grid-template-columns:repeat(4,1fr)}
  #en .med-row{grid-template-columns:1fr 1fr}
  #en .med-row>div:first-child,#en .med-row>div:nth-child(5){grid-column:1/-1}
}
@media(max-width:540px){
  #en .vg{grid-template-columns:repeat(2,1fr)}
  #en .pt{flex-wrap:wrap}
  #en .pt .ap{margin-left:0;text-align:left}
  #en .acts{justify-content:stretch}
  #en .acts button,#en .acts a.pb{flex:1}
}

#dd{--ink:#16324a;--mute:#5d7184;--line:#c9d6d0;--bg:#f3f8f5;--ok:#1d7a5f;--err:#b3261e;--now:#c47f17;max-width:780px;margin:0 auto;padding:16px 4px 48px;color:var(--ink);font:16px/1.5 system-ui,-apple-system,"Segoe UI",Roboto,sans-serif}
#dd *{box-sizing:border-box}
#dd h1{font-size:1.7rem;margin:0 0 12px;letter-spacing:-.01em}
#dd .bar{display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin-bottom:12px}
#dd input,#dd select{padding:10px 12px;border:1.5px solid var(--line);border-radius:8px;font:inherit;color:var(--ink);background:#fff}
#dd .bar select{flex:1 1 200px;min-width:0}
#dd button,#dd a.btn{padding:10px 14px;border:1.5px solid var(--ink);border-radius:8px;background:#fff;color:var(--ink);font:inherit;font-weight:600;cursor:pointer;text-decoration:none;display:inline-block}
#dd input:focus,#dd select:focus,#dd button:focus-visible,#dd a:focus-visible{outline:3px solid #8cc9b5;outline-offset:1px}
#dd .chips{display:flex;flex-wrap:wrap;gap:8px;margin:4px 0 16px}
#dd .chips button{padding:6px 12px;border-color:var(--line);font-weight:500}
#dd .chips button[aria-pressed=true]{background:var(--ink);border-color:var(--ink);color:#fff}
#dd .a{display:grid;grid-template-columns:96px 1fr;gap:4px 14px;padding:14px;margin-bottom:10px;border:1.5px solid var(--line);border-left:6px solid var(--ink);border-radius:10px;background:#fff}
#dd .a.now{border-left-color:var(--now);background:#fff9ec}
#dd .a.done{border-left-color:var(--line);opacity:.78}
#dd .t strong{display:block;font-size:1.05rem}
#dd .t span,#dd .m{color:var(--mute);font-size:.92rem}
#dd .a h3{margin:0;font-size:1.1rem}
#dd .m{margin:2px 0}
#dd .m span{margin-right:14px}
#dd .n{margin:6px 0 0;padding:8px 10px;background:var(--bg);border-radius:6px;font-size:.95rem}
