#apt{--ink:#16324a;--mute:#5d7184;--line:#c9d6d0;--bg:#f3f8f5;--ok:#1d7a5f;--err:#b3261e;max-width:560px;margin:0 auto;padding:16px 4px 48px;color:var(--ink);font:16px/1.5 system-ui,-apple-system,"Segoe UI",Roboto,sans-serif}
#apt *{box-sizing:border-box}
#apt h1{font-size:1.7rem;margin:0 0 4px;letter-spacing:-.01em}
#apt .lead{color:var(--mute);margin:0 0 20px}
#apt .seg{display:grid;grid-template-columns:1fr 1fr;border:1.5px solid var(--ink);border-radius:10px;overflow:hidden;margin-bottom:20px}
#apt .seg button{padding:12px 8px;border:0;background:#fff;color:var(--ink);font:inherit;font-weight:600;cursor:pointer}
#apt .seg button[aria-pressed=true]{background:var(--ink);color:#fff}
#apt fieldset{border:0;padding:0;margin:0 0 22px}
#apt legend{font-weight:700;font-size:1.05rem;padding:0;margin-bottom:10px}
#apt label{display:block;font-size:.92rem;font-weight:600;margin:12px 0 4px}
#apt input,#apt select,#apt textarea{width:100%;padding:11px 12px;border:1.5px solid var(--line);border-radius:8px;font:inherit;color:var(--ink);background:#fff}
#apt input:focus,#apt select:focus,#apt textarea:focus,#apt button:focus-visible{outline:3px solid #8cc9b5;outline-offset:1px}
#apt .row{display:grid;grid-template-columns:1fr 1fr;gap:12px}
#apt .go{width:100%;margin-top:16px;padding:13px;border:0;border-radius:10px;background:var(--ok);color:#fff;font:inherit;font-weight:700;cursor:pointer}
#apt .go:disabled{opacity:.55;cursor:wait}
