#apt .note{margin-top:12px;padding:12px 14px;border-radius:8px;background:var(--bg);border-left:4px solid var(--ok)}
#apt .note.bad{border-color:var(--err);background:#fdf0ef}
#apt .slots{display:flex;flex-wrap:wrap;gap:8px;margin-top:6px}
