#apt .slots button[aria-pressed=true]{background:var(--ink);border-color:var(--ink);color:#fff}
#apt .res{display:grid;gap:8px;margin-top:12px}
#apt .res button{display:flex;flex-wrap:wrap;gap:2px 16px;align-items:baseline;text-align:left;width:100%;padding:11px 13px;border:1.5px solid var(--line);border-radius:8px;background:#fff;color:var(--ink);font:inherit;cursor:pointer}
